<script setup>
import {ref,computed,nextTick,onMounted,onBeforeUnmount} from 'vue';
import {ArrowLeft,RotateCcw,Check,X,Plus,Search,Box,Layers,Upload,Move3D,Rotate3D,Scaling,Undo2,Redo2,Eye,EyeOff,Lock,Unlock,Copy,Trash2,Focus,Grid2X2,Magnet,MousePointer2,MapPin,Play,Pause,Camera,ChevronDown,ChevronRight,ArrowDownToLine,LoaderCircle,TriangleAlert,PackageOpen} from 'lucide-vue-next';
import SpatialScene from './SpatialScene.vue';import Control from './Control.vue';import SceneAssetPreview from './SceneAssetPreview.vue';
import {scenePresets,modelPresets,materialPresets,makeSceneObject,normalizeSceneObjects,cloneSceneObject} from '../scene/config.js';import './scene-editor.css';
const props=defineProps({node:Object,theme:Object,assets:Object,modelAssets:Array,uploadModels:Function,includeAsset:Function});const emit=defineEmits(['apply','cancel']);
const draft=ref(JSON.parse(JSON.stringify(props.node)));draft.value.props.sceneObjects=normalizeSceneObjects(draft.value.props.sceneObjects);
const spatial=ref(),root=ref(),uploadInput=ref(),selectedId=ref(''),libraryTab=ref('assets'),category=ref('全部'),query=ref(''),inspectorTab=ref('properties'),mode=ref('translate'),space=ref('world'),snap=ref(false),grid=ref(true),playing=ref(false),preview=ref(false),placing=ref(false),placingObject=ref(false),uploading=ref(false),toast=ref(''),applying=ref(false),statuses=ref({}),history=ref([]),historyIndex=ref(-1);
const objects=computed(()=>draft.value.props.sceneObjects),selected=computed(()=>objects.value.find(o=>o.id===selectedId.value)),filtered=computed(()=>scenePresets.filter(p=>(category.value==='全部'||p.category===category.value)&&(p.name+p.category).includes(query.value))),models=computed(()=>(props.modelAssets||[]).filter(a=>a.type==='model'));
const stateName=computed(()=>({city:'数字城市',park:'智慧园区',industry:'工业产线',agriculture:'智慧农业'}[props.node.props.variant]||'3D 场景'));
let recordPending=false,toastTimer;
const canUndo=computed(()=>historyIndex.value>0),canRedo=computed(()=>historyIndex.value<history.value.length-1);
function snapshot(){return JSON.stringify({objects:objects.value,camera:draft.value.props.camera,target:draft.value.props.target});}
function commitHistory(){const s=snapshot();if(s===history.value[historyIndex.value])return;history.value.splice(historyIndex.value+1);history.value.push(s);if(history.value.length>60)history.value.shift();historyIndex.value=history.value.length-1;}
function record(){if(recordPending)return;recordPending=true;queueMicrotask(()=>{if(!recordPending)return;recordPending=false;commitHistory();});}
function travel(delta){recordPending=false;commitHistory();const i=historyIndex.value+delta;if(i<0||i>=history.value.length)return;historyIndex.value=i;const s=JSON.parse(history.value[i]);draft.value.props.sceneObjects=s.objects;draft.value.props.camera=s.camera;draft.value.props.target=s.target;if(!objects.value.some(o=>o.id===selectedId.value))selectedId.value='';}
function notify(s){toast.value=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',3400);}
function select(id){selectedId.value=id;placing.value=false;placingObject.value=false;}
function add(kind,extra={}){if(objects.value.length>=64){notify('每个场景最多添加 64 个对象');return;}preview.value=false;placing.value=false;placingObject.value=false;const n=objects.value.length;const o=makeSceneObject(kind,{position:[(n%4-1.5)*3,1.2,14+Math.floor(n/4)*2],...extra});objects.value.push(o);selectedId.value=o.id;inspectorTab.value=kind==='label'?'label':'properties';record();notify('已加入当前场景，可拖动坐标轴调整位置');return o;}
async function addModel(asset){try{await props.includeAsset?.(asset);add('glb',{name:asset.name,assetId:asset.id});}catch(e){notify(e.message);}}
async function upload(e){const files=[...e.target.files];e.target.value='';if(!files.length)return;if(files.some(f=>!/^.*\.(glb|gltf)$/i.test(f.name))){notify('请选择 GLB 或 glTF 模型文件');return;}if(objects.value.length+files.length>64){notify('每个场景最多添加 64 个对象');return;}uploading.value=true;try{const added=await props.uploadModels(files);for(const a of added)add('glb',{name:a.name,assetId:a.id});}catch(e){notify(e.message||'模型导入失败');}finally{uploading.value=false;}}
function remove(){if(!selected.value||selected.value.locked)return;draft.value.props.sceneObjects=objects.value.filter(o=>o.id!==selectedId.value);selectedId.value='';record();}
function duplicate(){if(!selected.value||selected.value.locked||objects.value.length>=64)return;const copy=cloneSceneObject(selected.value);objects.value.push(copy);selectedId.value=copy.id;record();}
function visibility(o){o.visible=!o.visible;record();}
function locked(o){o.locked=!o.locked;record();}
function material(m){if(!selected.value||selected.value.locked)return;selected.value.material={preset:m.id,...m};delete selected.value.material.id;delete selected.value.material.name;record();}
function transform(value){const o=objects.value.find(o=>o.id===value.id);if(!o||o.locked)return;for(const key of ['position','rotation','scale'])o[key]=value[key];}
function place(position){if(placingObject.value&&selected.value&&!selected.value.locked){selected.value.position=position.map(v=>Math.round(v*1000)/1000);placingObject.value=false;record();notify('模型已放置到选中的场景表面');}else add('label',{position});}
function placeObject(){if(!selected.value||selected.value.locked)return;placingObject.value=true;placing.value=false;preview.value=false;}
function initialView(){const view=spatial.value?.getView();if(view?.camera){draft.value.props.camera=view.camera;draft.value.props.target=view.target;record();notify('当前视角已设为大屏初始视角');}}
function apply(){if(applying.value)return;applying.value=true;emit('apply',{sceneObjects:normalizeSceneObjects(objects.value),camera:draft.value.props.camera,target:draft.value.props.target});}
function togglePreview(){preview.value=!preview.value;placing.value=false;placingObject.value=false;playing.value=preview.value;notify(preview.value?'点击标签或模型，体验配置的信息面板':'已返回场景编辑');}
function status(value){statuses.value={...statuses.value,[value.id]:value};}
function keyboard(e){
 if(e.key==='Tab'){const items=[...root.value.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex="0"]')].filter(el=>el.getClientRects().length);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0]?.focus();}return;}
 if(e.key==='Escape'){e.preventDefault();if(placing.value||placingObject.value){placing.value=false;placingObject.value=false;}else if(preview.value)preview.value=false;else selectedId.value='';return;}
 if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.target.isContentEditable)return;
 const meta=e.metaKey||e.ctrlKey,k=e.key.toLowerCase();if(meta&&k==='z'){e.preventDefault();travel(e.shiftKey?1:-1);}else if(meta&&k==='d'){e.preventDefault();duplicate();}else if(meta&&k==='s'){e.preventDefault();apply();}else if(['Delete','Backspace'].includes(e.key)){e.preventDefault();remove();}else if(k==='w')mode.value='translate';else if(k==='e')mode.value='rotate';else if(k==='r')mode.value='scale';else if(k==='f')spatial.value?.focusObject(selectedId.value);
}
onBeforeUnmount(()=>clearTimeout(toastTimer));record();onMounted(()=>nextTick(()=>root.value?.querySelector('button')?.focus()));
</script>
<template><div class="ase-backdrop"><section ref="root" class="aw-dialog ase-editor" role="dialog" aria-modal="true" aria-label="3D 场景编辑器" @keydown.stop="keyboard">
 <header class="ase-topbar"><div class="ase-brand"><button aria-label="取消场景编辑" title="返回大屏，放弃本次场景修改" :disabled="applying" @click="emit('cancel')"><ArrowLeft :size="18"/></button><span class="ase-brand-icon"><Box :size="21" :stroke-width="1.5"/></span><div><strong>Scene Studio <i>BETA</i></strong><small>{{stateName}}<ChevronRight :size="10"/>{{node.name}}</small></div></div><div class="ase-top-context"><span></span>在当前场景中，自由搭建</div><div class="ase-top-actions"><button class="ase-secondary" :disabled="applying" @click="emit('cancel')">取消</button><button class="ase-apply" :disabled="applying" @click="apply"><component :is="applying?LoaderCircle:Check" :class="{spin:applying}" :size="14"/>{{applying?'正在保存…':'应用并返回'}}</button></div></header>
 <aside class="ase-library"><div class="ase-library-tabs"><button :class="{active:libraryTab==='assets'}" @click="libraryTab='assets'"><PackageOpen :size="14"/>模型素材</button><button :class="{active:libraryTab==='objects'}" @click="libraryTab='objects'"><Layers :size="14"/>场景对象 <i>{{objects.length}}</i></button></div>
 <div v-if="libraryTab==='assets'" class="ase-library-scroll"><div class="ase-library-intro"><span>BUILD YOUR WORLD</span><h2>让场景，更有内容。</h2><p>选择模型，直接加入当前空间。</p></div><label class="ase-search"><Search :size="14"/><input v-model="query" aria-label="搜索场景模型" placeholder="搜索建筑、设备、能源…"/></label><div class="ase-categories"><button v-for="c in ['全部','建筑','设备','能源','环境']" :key="c" :class="{active:category===c}" @click="category=c">{{c}}</button></div><div class="ase-preset-grid"><button v-for="p in filtered" :key="p.id" :aria-label="'添加'+p.name+'到当前场景'" @click="add(p.id)"><div><SceneAssetPreview :kind="p.id" :color="p.color"/><i><Plus :size="12"/></i></div><strong>{{p.name}}</strong><small>{{p.subtitle}}</small></button><p v-if="!filtered.length" class="ase-empty-small">未找到匹配模型</p></div>
 <div class="ase-import-section"><h3>你的模型 <span>GLB / glTF</span></h3><button class="ase-upload" :disabled="uploading" @click="uploadInput.click()"><component :is="uploading?LoaderCircle:Upload" :class="{spin:uploading}" :size="18"/><strong>{{uploading?'正在导入模型…':'导入 GLB 模型'}}</strong><small>保留已有场景 · 单个最大 50 MB</small></button><button v-for="a in modelPresets" :key="a.id" class="ase-custom-model" :aria-label="'添加 GLB 素材 '+a.name" @click="add('glb',{name:a.name,url:a.url,fitSize:a.fitSize})"><Box :size="16"/><span>{{a.name}}<small>单体 GLB · 内置材质</small></span><Plus :size="13"/></button><button v-for="a in models" :key="a.id" class="ase-custom-model" @click="addModel(a)"><Box :size="16"/><span :title="a.name">{{a.name}}<small>本机模型素材</small></span><Plus :size="13"/></button><p class="ase-library-note">推荐自包含 GLB。glTF 的外部贴图和缓冲区需通过可访问的 URL 提供。</p></div></div>
 <div v-else class="ase-object-scroll"><div class="ase-scene-root"><Box :size="15"/><div><strong>{{stateName}}</strong><small>原有场景</small></div><span>BASE</span></div><div class="ase-object-heading"><span>新增对象</span><button aria-label="打开模型素材库" @click="libraryTab='assets'"><Plus :size="14"/></button></div><div v-if="!objects.length" class="ase-object-empty"><Layers :size="27" :stroke-width="1.2"/><strong>开始搭建你的场景</strong><p>从模型素材库中加入建筑或设备，或在画面中放置一个交互标签。</p><button @click="libraryTab='assets'">浏览模型素材 <ChevronRight :size="12"/></button></div><div v-for="o in objects" :key="o.id" class="ase-object-row" :class="{active:o.id===selectedId,hidden:!o.visible}"><button class="ase-object-select" :aria-label="'选择场景对象 '+o.name" @click="select(o.id)"><component :is="o.kind==='label'?MapPin:Box" :size="14"/><span>{{o.name}}<small>{{statuses[o.id]?.status==='loading'?'正在加载…':statuses[o.id]?.status==='error'?'加载失败':o.kind==='model'?'GLB / glTF':o.kind==='label'?'交互标签':'预设模型'}}</small></span></button><button :aria-label="(o.visible?'隐藏':'显示')+'场景对象 '+o.name" @click="visibility(o)"><component :is="o.visible?Eye:EyeOff" :size="12"/></button><button :aria-label="(o.locked?'解锁':'锁定')+'场景对象 '+o.name" @click="locked(o)"><component :is="o.locked?Lock:Unlock" :size="12"/></button></div></div>
 <footer class="ase-library-footer"><span class="ase-library-led"></span>修改应用到当前 3D 组件</footer></aside>
 <main class="ase-stage" :style="{'--aw-accent':theme.accent,'--aw-bg':'#102131','--aw-panel':'#182c3c','--aw-text':'#d8e6f1','--aw-muted':'#8199ac'}"><div class="ase-stage-shade"></div><SpatialScene ref="spatial" :node="draft" :theme="theme" :assets="assets" :playing="playing" :interactive="true" :editing="!preview" :selected-object-id="selectedId" :transform-mode="mode" :transform-space="space" :snap="snap" :editor-grid="grid" :placing-label="placing" :placing-object="placingObject" @object-select="select" @object-change="transform" @object-commit="record" @place="place" @object-status="status"/>
 <div class="ase-stage-caption"><span>SCENE / {{node.props.variant?.toUpperCase()||'CUSTOM'}}</span><strong>{{preview?'交互预览':'空间编辑模式'}}</strong></div>
 <div class="ase-toolbar" role="toolbar" aria-label="3D 场景工具"><div><button :disabled="!canUndo" aria-label="撤销场景修改" title="撤销 ⌘Z" @click="travel(-1)"><Undo2 :size="15"/></button><button :disabled="!canRedo" aria-label="重做场景修改" title="重做 ⌘⇧Z" @click="travel(1)"><Redo2 :size="15"/></button></div><i></i><div><button v-for="[m,label,icon,key] in [['translate','移动',Move3D,'W'],['rotate','旋转',Rotate3D,'E'],['scale','缩放',Scaling,'R']]" :key="m" :class="{active:mode===m&&!preview}" :aria-pressed="mode===m&&!preview" :aria-label="label+'场景对象'" :title="label+' '+key" :disabled="preview" @click="mode=m"><component :is="icon" :size="17"/></button></div><i></i><select v-model="space" aria-label="坐标空间" :disabled="preview"><option value="world">世界</option><option value="local">局部</option></select><button :class="{active:snap}" :aria-pressed="snap" aria-label="坐标吸附" title="移动 1m / 旋转 15° 吸附" :disabled="preview" @click="snap=!snap"><Magnet :size="15"/></button><button :class="{active:grid}" :aria-pressed="grid" aria-label="场景参考网格" :disabled="preview" @click="grid=!grid"><Grid2X2 :size="15"/></button><i></i><button :class="{active:placing}" aria-label="在场景中放置交互标签" :disabled="preview" @click="placing=!placing;placingObject=false"><MapPin :size="16"/></button></div>
 <div class="ase-stage-actions"><button :class="{active:preview}" @click="togglePreview"><Eye :size="14"/>{{preview?'返回编辑':'交互预览'}}</button><button aria-label="重置场景视角" title="重置场景视角" @click="spatial.reset()"><RotateCcw :size="14"/></button><button :aria-label="playing?'暂停场景动画':'播放场景动画'" @click="playing=!playing"><component :is="playing?Pause:Play" :size="14"/></button></div>
 <div v-if="placing||placingObject" class="ase-placement-hint"><MapPin :size="15"/>{{placingObject?'点击场景表面，放置选中模型':'点击场景表面，放置交互标签'}}<button @click="placing=false;placingObject=false">取消 <kbd>Esc</kbd></button></div>
 <div v-else-if="toast" class="ase-stage-toast" role="status"><Check :size="12"/>{{toast}}<button aria-label="关闭场景提示" @click="toast='' "><X :size="11"/></button></div>
 <div class="ase-stage-bottom"><span><i></i>{{objects.length}} 个新增对象 <b>·</b>{{preview?'点击模型或标签查看信息面板':'拖动坐标轴编辑 · 拖动画面旋转 · 滚轮缩放'}}</span><button @click="initialView"><Camera :size="13"/>设为初始视角</button></div>
 </main>
 <aside class="ase-inspector"><div class="ase-inspector-heading"><strong>对象设置</strong><span>实时预览</span></div><template v-if="selected"><div class="ase-selected-heading"><span>{{selected.kind==='label'?'ANNOTATION':selected.kind==='model'?'GLB MODEL':'SCENE OBJECT'}}</span><input v-model="selected.name" aria-label="场景对象名称" :disabled="selected.locked" maxlength="60" @change="record"/><div><button aria-label="聚焦选中场景对象" title="聚焦 F" @click="spatial.focusObject(selectedId)"><Focus :size="14"/></button><button aria-label="将选中模型放置到场景表面" title="点选场景表面放置" :disabled="selected.locked" @click="placeObject"><MousePointer2 :size="14"/></button><button aria-label="选中对象贴地" title="贴地" :disabled="selected.locked" @click="spatial.groundObject(selectedId)"><ArrowDownToLine :size="14"/></button><button aria-label="复制选中场景对象" :disabled="selected.locked" @click="duplicate"><Copy :size="14"/></button><button aria-label="删除选中场景对象" :disabled="selected.locked" @click="remove"><Trash2 :size="14"/></button></div></div><div v-if="statuses[selectedId]?.status==='error'" class="ase-load-error"><TriangleAlert :size="15"/><p>{{statuses[selectedId].message}}</p><button @click="spatial.retryObject(selectedId)">重试</button></div><div v-if="selected.locked" class="ase-lock-note"><Lock :size="12"/>对象已锁定<button @click="locked(selected)">解锁</button></div><div class="ase-property-tabs"><button :class="{active:inspectorTab==='properties'}" @click="inspectorTab='properties'">属性与材质</button><button :class="{active:inspectorTab==='label'}" @click="inspectorTab='label'">标签与面板<i v-if="selected.label.enabled"></i></button></div>
 <div class="ase-inspector-scroll" :key="selectedId"><fieldset :disabled="selected.locked"><template v-if="inspectorTab==='properties'"><section class="ase-section"><h3>空间变换 <span>TRANSFORM</span></h3><p class="ase-axis-caption">位置 <small>m</small></p><div class="ase-vector"><Control v-for="(a,i) in ['X','Y','Z']" :key="a" v-model="selected.position[i]" :label="'位置 '+a" :min="-200" :max="200" :step=".1" @commit="record"/></div><p class="ase-axis-caption">旋转 <small>°</small></p><div class="ase-vector"><Control v-for="(a,i) in ['X','Y','Z']" :key="a" v-model="selected.rotation[i]" :label="'旋转 '+a" :min="-360" :max="360" @commit="record"/></div><p class="ase-axis-caption">缩放 <small>×</small></p><div class="ase-vector"><Control v-for="(a,i) in ['X','Y','Z']" :key="a" v-model="selected.scale[i]" :label="'缩放 '+a" :min=".02" :max="40" :step=".05" @commit="record"/></div></section>
 <section v-if="selected.kind!=='label'" class="ase-section"><h3>材质预设 <span>{{materialPresets.length}} MATERIALS</span></h3><div class="ase-material-grid"><button v-for="m in materialPresets" :key="m.id" :disabled="selected.locked" :class="{active:selected.material.preset===m.id}" :aria-label="'应用材质 '+m.name" @click="material(m)"><i :class="'mat-'+m.id" :style="{'--mat-color':m.color}"></i><span>{{m.name}}</span><Check v-if="selected.material.preset===m.id" :size="10"/></button></div><template v-if="selected.material.preset!=='original'"><Control v-model="selected.material.color" label="材质颜色" type="color" @commit="record"/><Control v-model="selected.material.metalness" label="金属度" type="range" :min="0" :max="1" :step=".05" @commit="record"/><Control v-model="selected.material.roughness" label="粗糙度" type="range" :min="0" :max="1" :step=".05" @commit="record"/><Control v-model="selected.material.opacity" label="材质不透明度" type="range" :min=".05" :max="1" :step=".05" @commit="record"/><Control v-model="selected.material.emissive" label="自发光强度" type="range" :min="0" :max="3" :step=".05" @commit="record"/></template></section>
 <section class="ase-section"><h3>对象动效 <span>MOTION</span></h3><Control v-model="selected.animation.type" label="动效预设" type="select" :options="[{id:'none',name:'静止'},{id:'rotate',name:'缓慢旋转'},{id:'float',name:'悬浮起伏'},{id:'pulse',name:'呼吸脉动'}]" @commit="record"/><Control v-if="selected.animation.type!=='none'" v-model="selected.animation.speed" label="动效速度" type="range" :min=".1" :max="4" :step=".1" @commit="record"/><Control v-if="selected.kind==='model'" v-model="selected.animation.clips" label="播放 GLB 内置动画" type="toggle" @commit="record"/><p class="ase-field-note">点击画面右上方播放按钮，预览材质与对象动效。</p></section>
 <section v-if="selected.kind==='model'" class="ase-section"><h3>模型来源 <span>GLB / glTF</span></h3><p v-if="selected.assetId" class="ase-field-note">来自本机素材库，随项目包一同导出。</p><Control v-else v-model="selected.url" label="GLB / glTF 地址" type="text" @commit="record"/><Control v-model="selected.fitSize" label="模型适配尺寸" :min=".1" :max="80" :step=".1" unit="m" @commit="record"/><Control v-model="selected.draco" label="启用 Draco 解码" type="toggle" @commit="record"/></section></template>
 <template v-else><section class="ase-section"><h3>交互标签 <span>POI</span></h3><Control v-model="selected.label.enabled" label="显示交互标签" type="toggle" @commit="record"/><Control v-model="selected.label.title" label="标签标题" type="text" @commit="record"/><Control v-model="selected.label.color" label="标签强调色" type="color" @commit="record"/><Control v-model="selected.label.status" label="运行状态" type="select" :options="[{id:'normal',name:'运行正常'},{id:'warning',name:'需要关注'},{id:'offline',name:'离线'}]" @commit="record"/><p class="ase-axis-caption">标签偏移 <small>m</small></p><div class="ase-vector"><Control v-for="(a,i) in ['X','Y','Z']" :key="a" v-model="selected.label.offset[i]" :label="'标签偏移 '+a" :min="-100" :max="100" :step=".1" @commit="record"/></div></section>
 <section class="ase-section"><h3>弹出信息面板 <span>DETAIL PANEL</span></h3><Control v-model="selected.label.style" label="面板风格" type="select" :options="[{id:'glass',name:'光学玻璃'},{id:'solid',name:'深色实体'}]" @commit="record"/><label class="ase-description-label">介绍说明<textarea v-model="selected.label.description" aria-label="弹出面板介绍说明" rows="3" maxlength="500" @change="record"></textarea></label><div class="ase-data-heading"><span>信息字段</span><span>{{selected.label.rows.length}} / 8</span></div><div v-for="(r,i) in selected.label.rows" :key="i" class="ase-data-row"><div><input v-model="r.label" :aria-label="'信息字段'+(i+1)+'名称'" placeholder="指标名称" maxlength="30" @change="record"/><button :aria-label="'删除信息字段'+(i+1)" @click="selected.label.rows.splice(i,1);record()"><X :size="11"/></button></div><div><input v-model="r.value" :aria-label="'信息字段'+(i+1)+'数值'" placeholder="数值或文字" maxlength="100" @change="record"/><input v-model="r.unit" :aria-label="'信息字段'+(i+1)+'单位'" placeholder="单位" maxlength="16" @change="record"/></div></div><button class="ase-add-field" :disabled="selected.label.rows.length>=8" @click="selected.label.rows.push({label:'新指标',value:'—',unit:''});record()"><Plus :size="12"/>添加信息字段</button><Control v-model="selected.label.link" label="详情链接（可选）" type="text" @commit="record"/><Control v-if="selected.label.link" v-model="selected.label.linkText" label="链接按钮文字" type="text" @commit="record"/><p class="ase-field-note">支持 HTTP / HTTPS 链接。点击「交互预览」后，再点击标签查看效果。</p><button class="ase-test-label" @click="preview=true;placing=false;nextTick(()=>notify('点击场景中的标签，预览信息面板'))"><Eye :size="13"/>预览标签交互</button></section></template></fieldset></div></template>
 <div v-else class="ase-inspector-empty"><MousePointer2 :size="33" :stroke-width="1.2"/><h3>选中一个对象</h3><p>在画面或对象列表中选择模型，调整位置、材质与交互信息。</p><div><span>移动 / 旋转 / 缩放</span><kbd>W</kbd><kbd>E</kbd><kbd>R</kbd></div><div><span>聚焦选中对象</span><kbd>F</kbd></div><div><span>复制 / 撤销</span><kbd>⌘D</kbd><kbd>⌘Z</kbd></div><button @click="placing=true;placingObject=false;preview=false"><MapPin :size="14"/>放置交互标签</button></div>
 <footer class="ase-inspector-footer"><span></span>{{preview?'预览中的数据来自当前配置':'应用后随项目自动保存，可继续编辑'}}</footer></aside><input ref="uploadInput" type="file" multiple accept=".glb,.gltf" hidden @change="upload"/>
</section></div></template>
